\begin{definition}[Essential supremum]
\label{def:essential-supremum}
\dcref{appE:E.2-def-3}
\group{Measure Theory}
For a measurable real-valued function $f$,
\[
\operatorname*{ess\,sup}f
:=\inf\{\mu\in\mathbb R\mid |\{f>\mu\}|=0\}.
\]
\end{definition}

